package com.xebia.ums.info;

import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.info.BuildProperties;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * {@code GET /api/v1/info} (operationId: getServiceInfo). Version and build timestamp come from
 * {@code META-INF/build-info.properties}, generated by the spring-boot-maven-plugin build-info
 * goal.
 */
@RestController
public class InfoController {

  static final String UNKNOWN = "unknown";

  private final ObjectProvider<BuildProperties> buildProperties;
  private final ServiceInfoProperties serviceInfoProperties;

  public InfoController(
      ObjectProvider<BuildProperties> buildProperties,
      ServiceInfoProperties serviceInfoProperties) {
    this.buildProperties = buildProperties;
    this.serviceInfoProperties = serviceInfoProperties;
  }

  @GetMapping(path = "/api/v1/info", produces = MediaType.APPLICATION_JSON_VALUE)
  public ServiceInfoResponse getServiceInfo() {
    BuildProperties build = buildProperties.getIfAvailable();
    String version = build != null && build.getVersion() != null ? build.getVersion() : UNKNOWN;
    String environment =
        serviceInfoProperties.environment() != null ? serviceInfoProperties.environment() : UNKNOWN;
    return new ServiceInfoResponse(version, environment, build != null ? build.getTime() : null);
  }
}
